import{_ as i,a0 as l,w as p,s,ao as d,I as o,x as r,a1 as a,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const I=JSON.parse('{"title":"如何在 Linux 終端中知道你的公有 IP | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 終端中知道你的公有 IP | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 終端中知道你的公有 IP | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 終端中知道你的公有 IP | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150813 How to get Public IP from Linux Terminal","title":"如何在 Linux 終端中知道你的公有 IP","tag":"201508","desc":""},"relativePath":"201508/20150813 How to get Public IP from Linux Terminal.md","filePath":"[post].md"}'),c={name:"201508/20150813 How to get Public IP from Linux Terminal.md"};function u(h,e,m,x,f,g){const t=l("Link");return p(),s("div",null,[e[11]||(e[11]=d(`<h1 id="如何在-linux-終端中知道你的公有-ip" tabindex="-1">如何在 Linux 終端中知道你的公有 IP <a class="header-anchor" href="#如何在-linux-終端中知道你的公有-ip" aria-label="Permalink to “如何在 Linux 終端中知道你的公有 IP”">​</a></h1><p><img src="http://www.blackmoreops.com/wp-content/uploads/2015/06/256x256xHow-to-get-Public-IP-from-Linux-Terminal-blackMORE-Ops.png.pagespeed.ic.GKEAEd4UNr.png" alt=""></p><p>公有地址由 InterNIC 分配並由基於類的網絡 ID 或基於 CIDR 的地址塊構成（被稱為 CIDR 塊），並保證了在全球互聯網中的唯一性。當公有地址被分配時，其路由將會被記錄到互聯網中的路由器中，這樣訪問公有地址的流量就能順利到達。訪問目標公有地址的流量可經由互聯網抵達。比如，當一個 CIDR 塊被以網絡 ID 和子網掩碼的形式分配給一個組織時，對應的 [網絡 ID，子網掩碼] 也會同時作為路由儲存在互聯網中的路由器中。目標是 CIDR 塊中的地址的 IP 封包會被導向對應的位置。</p><p>在本文中我將會介紹在幾種在 Linux 終端中查看你的公有 IP 地址的方法。這對普通用户來説並無意義，但 Linux 服務器（無GUI或者作為只能使用基本工具的用户登錄時）會很有用。無論如何，從 Linux 終端中獲取公有 IP 在各種方面都很意義，説不定某一天就能用得着。</p><p>以下是我們主要使用的兩個命令，curl 和 wget。你可以換着用。</p><h3 id="curl-純文本格式輸出" tabindex="-1">Curl 純文本格式輸出: <a class="header-anchor" href="#curl-純文本格式輸出" aria-label="Permalink to “Curl 純文本格式輸出:”">​</a></h3><pre><code>curl icanhazip.com
curl ifconfig.me
curl curlmyip.com
curl ip.appspot.com
curl ipinfo.io/ip
curl ipecho.net/plain
curl www.trackip.net/i
</code></pre><h3 id="curl-json格式輸出" tabindex="-1">curl JSON格式輸出: <a class="header-anchor" href="#curl-json格式輸出" aria-label="Permalink to “curl JSON格式輸出:”">​</a></h3><pre><code>curl ipinfo.io/json
curl ifconfig.me/all.json
curl www.trackip.net/ip?json (有點醜陋)
</code></pre><h3 id="curl-xml格式輸出" tabindex="-1">curl XML格式輸出: <a class="header-anchor" href="#curl-xml格式輸出" aria-label="Permalink to “curl XML格式輸出:”">​</a></h3><pre><code>curl ifconfig.me/all.xml
</code></pre><h3 id="curl-得到所有ip細節-挖掘機" tabindex="-1">curl 得到所有IP細節 （挖掘機）### <a class="header-anchor" href="#curl-得到所有ip細節-挖掘機" aria-label="Permalink to “curl 得到所有IP細節 （挖掘機）###”">​</a></h3><pre><code>curl ifconfig.me/all
</code></pre><h3 id="使用-dydns-當你使用-dydns-服務時有用" tabindex="-1">使用 DYDNS （當你使用 DYDNS 服務時有用）### <a class="header-anchor" href="#使用-dydns-當你使用-dydns-服務時有用" aria-label="Permalink to “使用 DYDNS （當你使用 DYDNS 服務時有用）###”">​</a></h3><pre><code>curl -s &#39;http://checkip.dyndns.org&#39; | sed &#39;s/.*Current IP Address: \\([0-9\\.]*\\).*/\\1/g&#39; 
curl -s http://checkip.dyndns.org/ | grep -o &quot;[[:digit:].]\\+&quot;
</code></pre><h3 id="使用-wget-代替-curl" tabindex="-1">使用 Wget 代替 Curl <a class="header-anchor" href="#使用-wget-代替-curl" aria-label="Permalink to “使用 Wget 代替 Curl”">​</a></h3><pre><code>wget http://ipecho.net/plain -O - -q ; echo
wget http://observebox.com/ip -O - -q ; echo
</code></pre><h3 id="使用-host-和-dig-命令" tabindex="-1">使用 host 和 dig 命令 <a class="header-anchor" href="#使用-host-和-dig-命令" aria-label="Permalink to “使用 host 和 dig 命令”">​</a></h3><p>如果有的話，你也可以直接使用 host 和 dig 命令。</p><pre><code>host -t a dartsclink.com | sed &#39;s/.*has address //&#39;
dig +short myip.opendns.com @resolver1.opendns.com
</code></pre><h3 id="bash-腳本示例" tabindex="-1">bash 腳本示例: <a class="header-anchor" href="#bash-腳本示例" aria-label="Permalink to “bash 腳本示例:”">​</a></h3><pre><code>#!/bin/bash

PUBLIC_IP=\`wget http://ipecho.net/plain -O - -q ; echo\`
echo $PUBLIC_IP
</code></pre><p>簡單易用。</p><p>我實際上是在寫一個用於記錄每日我的路由器中所有 IP 變化並保存到一個文件的腳本。我在搜索過程中找到了這些很好用的命令。希望某天它能幫到其他人。</p><hr>`,25)),o("p",null,[e[1]||(e[1]=r("via: ",-1)),a(t,{href:"http://www.blackmoreops.com/2015/06/14/how-to-get-public-ip-from-linux-terminal/"},{default:n(()=>[...e[0]||(e[0]=[r("http://www.blackmoreops.com/2015/06/14/how-to-get-public-ip-from-linux-terminal/",-1)])]),_:1})]),o("p",null,[e[4]||(e[4]=r("譯者：",-1)),a(t,{href:"https://github.com/KevinSJ"},{default:n(()=>[...e[2]||(e[2]=[r("KevinSJ",-1)])]),_:1}),e[5]||(e[5]=r(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:n(()=>[...e[3]||(e[3]=[r("wxy",-1)])]),_:1})]),o("p",null,[e[8]||(e[8]=r("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[6]||(e[6]=[r("LCTT",-1)])]),_:1}),e[9]||(e[9]=r(" 原創翻譯，",-1)),a(t,{href:"https://linux.cn/"},{default:n(()=>[...e[7]||(e[7]=[r("Linux中國",-1)])]),_:1}),e[10]||(e[10]=r(" 榮譽推出",-1))])])}const w=i(c,[["render",u]]);export{I as __pageData,w as default};
